const MODAL_CONSUMOS_CREDITOS_ID = 'modal-consumos-creditos';

let empresa_plan_creditos = null;
let empresa_plan_id_creditos = null;
let filas_seleccionadas_creditos = [];
let filas_creditos= [];

/**
 * Abrir la modal de detalle de consumo de créditos IA.
 *
 * @param {number} empresa_plan_id Id de la empresa.
 * @param {number} plan_id Id del registro de la tabla empresas_planes.
 * @param {string} nombre_plan Nombre del plan.
 * @returns {void}
 * @author Jair Carvajal
 */
function abrirModalConsumosCreditos(empresa_plan_id, plan_id, nombre_plan) {
    $('#nombre-plan-creditos').text(nombre_plan);
    empresa_plan_creditos = empresas_planes.find(plan => plan.id === plan_id);
    actualizarBarraProgresoCreditos();

    establecerEventoDescargarCreditosExcel(empresa_plan_id);
    renderTablaConsumosCreditos(empresa_plan_id);

    $(`#${MODAL_CONSUMOS_CREDITOS_ID}`).modal('show');
}

/**
 * Actualiza la barra de progreso de créditos totales.
 *
 * @returns {void}
 * @author Jair Carvajal
 */
function actualizarBarraProgresoCreditos() {
    let creditos_consumidos = (empresa_plan_creditos?.creditos_restantes ?? 0);
    let creditos_totales = empresa_plan_creditos?.creditos ?? 1;
    let porcentaje = (creditos_consumidos / creditos_totales) * 100;

    const CONTENIDO = `
        <p class="text-label-2 mb-1">
            <img class="me-2" src="/iconos/icono_ia.svg" width="16" height="16" alt="Icono IA"> Créditos
        </p>
        ${crearProgressBar({
            label: `${creditos_consumidos}/${creditos_totales}`,
            height: '8px',
            porcentaje: { porcentaje, texto: false }
        })}
    `;

    $('#creditos-totales-consumidos').empty().append(CONTENIDO);
}

/**
 * Renderiza la tabla de consumos de créditos IA.
 *
 * @param {number} empresa_plan_id Id del registro de la tabla empresas_planes.
 * @returns {void}
 * @author Jair Carvajal
 */
function renderTablaConsumosCreditos(empresa_plan_id) {
    let nombre_tabla = 'tabla-consumos-creditos';
    destruirTablaExistente(nombre_tabla);

    $(`#${nombre_tabla}`).DataTable({
        ...configuracion_tablas,
        ajax: {
            url: `empresas/${empresa_plan_id}/consumos-creditos`,
            data: function(parametros) {
                parametros.servicio_ia_id = $('#servicio_ia_filtro').val() || null;
                parametros.usuario_id = $('#usuario_filtro').val() || null;

                let fecha_rango = $('#fecha_creacion_filtro').val();
                if (fecha_rango) {
                    let fechas = fecha_rango.split(' a ');
                    parametros.desde = fechas[0] || null;
                    parametros.hasta = fechas[1] || fechas[0] || null;
                }

                return parametros;
            }
        },
        columns: [
            {
                data: null,
                orderable: false,
                searchable: false,
                title: `${
                    crearCheckbox({
                        id: 'checkbox-seleccionar-todos-tabla-consumos-creditos',
                        name: 'checkbox-seleccionar-todos-tabla-consumos-creditos',
                        onclick: 'seleccionarTodosConsumosCreditos(this.checked)'
                    })
                }`,
                render: (dato, tipo, fila, meta) => {
                    let fila_id = meta.row;
                    let fila_seleccionada = filas_seleccionadas_creditos.includes(fila_id);
                    return crearCheckbox({
                        id: `credito-${fila_id}`,
                        class: 'checkbox-tabla-consumos-creditos',
                        name: 'checkbox',
                        checked: fila_seleccionada,
                        onclick: `seleccionarConsumoCredito(this.checked, ${fila_id})`,
                    });
                },
            },
            {
                title: '<span class="text-body-3">Servicio</span>',
                data: 'servicio',
                className: 'text-body-3',
                orderable: true,
                searchable: true,
                render: (dato, tipo) => (tipo === 'display') ? (dato ?? '---') : dato
            },
            {
                title: '<span class="text-body-3">Usuario</span>',
                data: 'usuario',
                className: 'text-body-3',
                orderable: true,
                searchable: true,
                render: (dato, tipo) => (tipo === 'display') ? (dato?.nombre_completo ?? '---') : (dato?.nombre_completo ?? '')
            },
            {
                title: '<span class="text-body-3">Créditos</span>',
                data: 'creditos',
                className: 'text-body-3',
                orderable: true,
                searchable: false,
                render: (dato, tipo) => (tipo === 'display') ? (dato ?? '---') : dato
            },
            {
                title: '<span class="text-body-3">Fecha de consumo</span>',
                data: 'fecha_consumo',
                className: 'text-body-3',
                orderable: true,
                searchable: true,
                render: (dato, tipo) => (tipo === 'display') ? (dato ? formatearFechaConceptual(dato, false, 'dmY', '-').fecha : '---') : dato
            },
        ],
        initComplete: function() {
            cargarDataTablas();
        },
        drawCallback: function() {
            const DATOS = $(`#tabla-consumos-creditos`).DataTable().data().toArray();
            filas_creditos= DATOS.map((_, indice) => indice);
            inicializarTooltips();
        },
    });
}

/**
 * Establecer el evento para el botón de descarga del archivo Excel de créditos.
 *
 * @param {number} empresa_plan_id Id de registro de la tabla empresas_planes.
 * @returns {void}
 * @author Jair Carvajal
 */
function establecerEventoDescargarCreditosExcel(empresa_plan_id) {

    let ruta_descarga = `consumos-creditos-ia-exportar`;

    $('#boton-descargar-tabla-consumos-creditos').off('click').on('click', () => {
        let consumos_ids = filas_seleccionadas_creditos.length ? [...filas_seleccionadas_creditos] : [];
        let parametros = consumos_ids.length ? { ids_consumos: consumos_ids, empresa_id: empresa_plan_id } : { empresa_id: empresa_plan_id };
        descargarExcel(ruta_descarga, 'consumos_creditos_ia', true, parametros);
    });
}

/**
 * Seleccionar o deseleccionar todos los consumos de créditos.
 *
 * @param {boolean} seleccion Selección.
 * @returns {void}
 * @author Jair Carvajal
 */
function seleccionarTodosConsumosCreditos(seleccion) {
    filas_seleccionadas_creditos = [];
    if (seleccion) {
        filas_seleccionadas_creditos = [...filas_creditos_ids];
    }
    actualizarDatatables('tabla-consumos-creditos');
}

/**
 * Selecciona o deselecciona un consumo de crédito.
 *
 * @param {boolean} seleccion Selección.
 * @param {number} fila_id Id de la fila de la tabla.
 * @returns {void}
 * @author Jair Carvajal
 */
function seleccionarConsumoCredito(seleccion, fila_id) {
    const NUMERO_ID = parseInt(fila_id);

    if (seleccion) {
        if (!filas_seleccionadas_creditos.includes(NUMERO_ID)) {
            filas_seleccionadas_creditos.push(NUMERO_ID);
        }
    } else {
        filas_seleccionadas_creditos = filas_seleccionadas_creditos.filter(id => id !== NUMERO_ID);
    }

    validarSeleccionCreditos();
}

/**
 * Validar los consumos de créditos seleccionados.
 *
 * @returns {void}
 * @author Jair Carvajal
 */
function validarSeleccionCreditos() {
    let seleccionados = filas_seleccionadas_creditos.length;
    let total = filas_creditos_ids.length;
    let seleccionado_todos = $('#checkbox-seleccionar-todos-tabla-consumos-creditos');

    if (seleccionados === 0) {
        seleccionado_todos.prop('indeterminate', false);
        seleccionado_todos.prop('checked', false);
    } else if (seleccionados === total && total > 0) {
        seleccionado_todos.prop('indeterminate', false);
        seleccionado_todos.prop('checked', true);
    } else {
        seleccionado_todos.prop('indeterminate', true);
    }
}

/**
 * Aplica los filtros del dropdown de filtros avanzados.
 * Esta función es llamada automáticamente por el componente crearFiltroDropdown.
 *
 * @param {string} campo_id Id del filtro dropdown.
 * @param {object} filtros Objeto con los filtros aplicados.
 * @returns {void}
 * @author Jair Carvajal
 */
function aplicarFiltrosDropdown(campo_id, filtros) {
    if (campo_id === 'filtro_empresas') {
        actualizarDatatables('tabla-consumos-creditos');
    }
}

