            <td style="border: 1px solid #000000;">{{ $item['creditos'] ?? 0 }}</td>
            <td style="border: 1px solid #000000;">{{ $item['tokens_reales'] ?? 0 }}</td>
            <td style="border: 1px solid #000000;">{{ isset($item['fecha_consumo']) ? $item['fecha_consumo']->format('Y-m-d H:i:s') : '---' }}</td>
        </tr>
    @endforeach
@endsection
```

**2.** En el controlador `EmpresaPlanController.php`, modificar el método `exportarExcelConsumosCreditosIA` (líneas 519-531):

- Cambiar la plantilla de `'excel.empresas.historial-creditos'` a `'excel.empresas.consumos-creditos-ia'`
- Agregar `.xlsx` al nombre del archivo

```php
public function exportarExcelConsumosCreditosIA(int $empresa_id, Request $request): BinaryFileResponse {
    return Excel::download(
        new GlobalExport(
            ['Usuario', 'Servicio', 'Créditos', 'Tokens reales', 'Fecha consumo'],
            $this->consumo_credito_servicio->historialConsumosEmpresa($empresa_id, $request->all()),
            'Consumos Créditos IA',
            'excel.empresas.consumos-creditos-ia'  // ← Plantilla correcta
        ),
        'consumos-creditos-ia.xlsx'  // ← Agregar extensión
    );
}
```

